/* eslint-disable */
/* prettier-ignore */

/* auto-generated by NAPI-RS */

export interface PageImage {
  widthPx: number
  heightPx: number
  /** PNG bytes. Available as a Buffer on the JS side. */
  png: Buffer
}

export interface LicenseInfo {
  licensed: boolean
  tier?: string
}

/**
 * Template JSON + data JSON -> one PNG image per page (96dpi, for on-screen preview).
 * An empty data JSON is treated as no rows ({"Parameters":{"Data":[]}}).
 */
export function renderPreview(templateJson: string, dataJson: string): Array<PageImage>

/**
 * Template JSON + data JSON -> PDF file (72dpi). Returns the page count.
 */
export function renderPdf(templateJson: string, dataJson: string, outputPath: string): number

/**
 * Template JSON + data JSON -> ACR-PNG-PACKAGE ZIP (manifest.json + pages/NNN.png, 96dpi).
 * Returns the page count.
 */
export function renderPngZip(templateJson: string, dataJson: string, outputPath: string, engineVersion: string): number

/**
 * Template JSON -> JSON string listing DataField names used in it and where each is used.
 */
export function listDataFields(templateJson: string): string

/**
 * Current license status, read from the local cache (no network call).
 */
export function licenseStatus(): LicenseInfo

/**
 * Activates a license key against the ACR license server and caches the result
 * locally. Returns the license tier on success.
 */
export function activate(email: string, key: string): string
